// Checks the request was signed by fedramp-auto with FEDRAMP_WEBHOOK_SECRET
// (HMAC-SHA256 of the raw body, header X-FedRAMP-Auto-Signature).
// Never throws: "Respond" answers 202 or 401, then "Accept scan" stops rejected requests.
// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto and the Webhook node's "Raw Body" option.
const crypto = require('crypto');
const secret = $env.FEDRAMP_WEBHOOK_SECRET || '';
const item = $input.first();
const headers = item.json.headers || {};
const body = item.json.body || {};

async function check() {
  if (secret) {
    let raw;
    try {
      raw = await this.helpers.getBinaryDataBuffer(0, 'data');
    } catch (e) {
      const data = item.binary && item.binary.data && item.binary.data.data;
      if (!data) return 'Raw body missing: turn on "Raw Body" in the Webhook node options';
      raw = Buffer.from(data, 'base64');
    }
    const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex');
    const got = String(headers['x-fedramp-auto-signature'] || '');
    const ok = got.length === expected.length &&
      crypto.timingSafeEqual(Buffer.from(got), Buffer.from(expected));
    if (!ok) return 'Bad or missing X-FedRAMP-Auto-Signature';
  } else if (String($env.FEDRAMP_ALLOW_UNSIGNED || '').toLowerCase() !== 'true') {
    return 'FEDRAMP_WEBHOOK_SECRET is not set (or set FEDRAMP_ALLOW_UNSIGNED=true)';
  }
  if (body.event !== 'fedramp_auto.scan.completed') return 'Unexpected event: ' + body.event;
  return null;
}

const error = await check.call(this);
return [{ json: error ? { ok: false, error } : { ok: true, scan: body } }];

// Rejected requests were already answered with 401; stop them here so the
// execution shows as failed in n8n. Accepted ones continue as the scan payload.
const { ok, error, scan } = $input.first().json;
if (!ok) throw new Error('Rejected: ' + error);
return [{ json: scan }];

// One Slack message per scan that changed something (always for the first scan).
const scan = $input.first().json;
const s = scan.summary;
const c = scan.coverage;
const changed = !s.has_previous || s.new_gaps > 0 || s.resolved_gaps > 0 || (c.delta || 0) !== 0;
if (!changed || !$env.FEDRAMP_SLACK_WEBHOOK_URL) return [];

const icon = s.new_critical_gaps > 0 ? ':red_circle:'
  : s.new_gaps > 0 ? ':large_orange_circle:' : ':large_green_circle:';
const delta = c.delta === null ? '' : ` (${c.delta >= 0 ? '+' : ''}${c.delta} pts)`;
const list = (gaps) => gaps.slice(0, 10)
  .map((g) => `• *${g.ksi_id}* ${g.title} _(${g.severity})_`).join('\n')
  + (gaps.length > 10 ? `\n…and ${gaps.length - 10} more` : '');

const lines = [
  `${icon} *FedRAMP-Auto* · ${scan.target} · ${String(scan.baseline).toUpperCase()} baseline`,
  `KSI coverage *${c.pct}%*${delta} · ${c.satisfied_ksis}/${c.total_ksis} KSIs · ` +
    `${s.open_gaps} open gap(s), ${s.critical_gaps} critical`,
];
if (!s.has_previous && s.open_gaps) lines.push(`*Open gaps:*\n${list(scan.open_gaps)}`);
if (s.has_previous && s.new_gaps) lines.push(`*New gaps (${s.new_gaps}):*\n${list(scan.new_gaps)}`);
if (s.resolved_gaps) lines.push(`*Resolved (${s.resolved_gaps}):*\n${list(scan.resolved_gaps)}`);
if (scan.ci) lines.push(`<${scan.ci.url}|View run>`);
return [{ json: { text: lines.join('\n') } }];

// One GitHub issue per new gap at a severity in FEDRAMP_ISSUE_SEVERITIES.
const scan = $input.first().json;
const repo = String($env.FEDRAMP_GITHUB_REPO || '');
if (!/^[\w.-]+\/[\w.-]+$/.test(repo)) return [];
const wanted = String($env.FEDRAMP_ISSUE_SEVERITIES || 'critical,high')
  .split(',').map((s) => s.trim().toLowerCase());
const fence = '```';

return scan.new_gaps.filter((g) => wanted.includes(g.severity)).map((g) => {
  const r = g.remediation || {};
  const body = [
    `**Severity:** ${g.severity}`,
    `**Baseline:** ${scan.baseline}`,
    `**Missing NIST 800-53 controls:** ${g.missing_controls.join(', ')}`,
    '',
  ];
  if (r.risk_explanation) body.push('### Risk', r.risk_explanation, '');
  if (r.remediation_action) body.push('### Fix', r.remediation_action, '');
  if (r.terraform_snippet) body.push(fence + (r.snippet_language || 'hcl'), r.terraform_snippet, fence, '');
  body.push(scan.ci
    ? `Found by [this run](${scan.ci.url}) on \`${String(scan.ci.sha || '').slice(0, 7)}\`.`
    : `Found by a scan at ${scan.generated_at}.`);
  body.push('', '_Opened by FedRAMP-Auto via n8n. Closed automatically when a later scan ' +
    'no longer reports this gap._');
  return { json: {
    repo,
    title: `[FedRAMP-Auto] ${scan.target} ${g.ksi_id}: ${g.title}`,
    body: body.join('\n'),
    labels: ['fedramp-auto', `severity:${g.severity}`],
  } };
});

// One item per resolved gap, so its open issue can be found and closed.
const scan = $input.first().json;
const repo = String($env.FEDRAMP_GITHUB_REPO || '');
if (!/^[\w.-]+\/[\w.-]+$/.test(repo)) return [];
return scan.resolved_gaps.map((g) => ({ json: {
  repo,
  ksi_id: g.ksi_id,
  prefix: `[FedRAMP-Auto] ${scan.target} ${g.ksi_id}:`,
} }));

// Keep only open issues whose title starts with the resolved gap's exact prefix.
// The search request runs once per "Resolved gaps" item, in the same order.
const wanted = $('Resolved gaps').all();
const out = [];
$input.all().forEach((item, i) => {
  const want = wanted[i] && wanted[i].json;
  if (!want) return;
  for (const issue of item.json.items || []) {
    if (String(issue.title).startsWith(want.prefix)) {
      out.push({ json: { repo: want.repo, number: issue.number, ksi_id: want.ksi_id } });
    }
  }
});
return out;
